const OPEN_LIMIT = 120_000;

// Open a file in a decode worker, giving up after OPEN_LIMIT.
export function openWithLimit(worker, file) {
  return new Promise((resolve, reject) => {
    const timer = setTimeout(
      () => reject(new Error('open ' + file.name + ' timed out after ' + OPEN_LIMIT / 1000 + ' s')),
      OPEN_LIMIT,
    );
    worker.post({ op: 'open', file }).then(
      (handle) => {
        clearTimeout(timer);
        resolve(handle);
      },
      (error) => {
        clearTimeout(timer);
        reject(error);
      },
    );
  });
}

