// The time limit for opening a file: 120 s, plus 1 s per 10 MB.
export const openLimit = (bytes) => 120_000 + Math.ceil(bytes / 10e6) * 1000;

// Open a file in a decode worker, giving up after openLimit(file.size).
export function openWithLimit(worker, file) {
  const limit = openLimit(file.size);
  return new Promise((resolve, reject) => {
    const timer = setTimeout(
      () => reject(new Error('open ' + file.name + ' timed out after ' + limit / 1000 + ' s')),
      limit,
    );
    worker.post({ op: 'open', file }).then(
      (handle) => {
        clearTimeout(timer);
        resolve(handle);
      },
      (error) => {
        clearTimeout(timer);
        reject(error);
      },
    );
  });
}

