import { test } from 'node:test';
import assert from 'node:assert/strict';
import { openLimit, openWithLimit } from '../src/open.js';

test('the limit is 120 s plus 1 s per 10 MB', () => {
  assert.equal(openLimit(0), 120_000);
  assert.equal(openLimit(5e6), 121_000);
  assert.equal(openLimit(1.85e9), 305_000);
});

test('a file that opens in time resolves with its handle', async () => {
  const worker = { post: async () => 'handle-1' };
  assert.equal(await openWithLimit(worker, { name: 'a.nc', size: 1e6 }), 'handle-1');
});
